/**
 * Generates the CSS token files in packages/tailwind-config from the
 * canonical theme in packages/design-system/src/tokens.ts.
 *
 *   pnpm tokens:generate   write the files
 *   pnpm tokens:check      exit 1 if any committed file is out of date (CI)
 *
 * Outputs (all fully generated — do not edit by hand):
 *   - variables.css    web: light on :root, dark under `.dark`
 *   - native-theme.css Uniwind: `@variant light` / `@variant dark`
 *   - suit-tokens.css  web base styles + `--suit-color-bg` legacy alias
 *
 * Web has one theme mechanism: the `dark` class on <html>.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import process from 'node:process';

import { suitThemeDark, suitThemeLight } from '../packages/design-system/src/tokens';

type Colors = typeof suitThemeLight.colors;
type ColorKey = keyof Colors;

const OUT_DIR = resolve(process.cwd(), 'packages/tailwind-config');
const HEADER =
  '/* GENERATED by scripts/generate-design-tokens.ts from\n' +
  ' * packages/design-system/src/tokens.ts — do not edit. Run `pnpm tokens:generate`. */\n';

const theme = suitThemeLight;
const px = (value: number) => `${value}px`;

/** CSS variable suffix → theme color key, in emission order. */
const colorVars: Array<[string, ColorKey]> = [
  ['background', 'background'],
  ['background-canvas', 'backgroundCanvas'],
  ['background-canvas-top', 'backgroundCanvasTop'],
  ['background-canvas-cool', 'backgroundCanvasCool'],
  ['surface', 'surface'],
  ['accent', 'accent'],
  ['text', 'text'],
  ['muted', 'muted'],
  ['success', 'success'],
  ['destructive', 'destructive'],
  ['warning', 'warning'],
  ['caution', 'caution'],
  ['info', 'info'],
  ['neutral', 'neutral'],
];
const brandVars: Array<[string, ColorKey]> = [
  ['brand-primary', 'brandPrimary'],
  ['brand-secondary', 'brandSecondary'],
  ['brand-accent', 'brandAccent'],
  ['brand-light', 'brandLight'],
  ['brand-dark', 'brandDark'],
];

/** `"Zilla Slab", serif` / `Arvo, serif` → `'Zilla Slab', serif`. */
function cssFontStack(stack: string): string {
  const [family = '', ...fallbacks] = stack.split(',').map((part) => part.trim());
  return [`'${family.replace(/^["']|["']$/g, '')}'`, ...fallbacks].join(', ');
}

interface FontSet {
  arvo: string;
  amaranth: string;
  zilla: string;
  arvoBold: string;
  amaranthBold: string;
  zillaLight: string;
  zillaBold: string;
}

const webArvo = cssFontStack(theme.fontFamilies.web.arvo);
const webAmaranth = cssFontStack(theme.fontFamilies.web.amaranth);
const webZilla = cssFontStack(theme.fontFamilies.web.zillaSlab);
const native = (name: string) => `'${name}'`;

const fonts: { web: FontSet; native: FontSet } = {
  // Web: weighted families alias the base family; weight comes from font-*.
  web: {
    arvo: webArvo,
    amaranth: webAmaranth,
    zilla: webZilla,
    arvoBold: webArvo,
    amaranthBold: webAmaranth,
    zillaLight: webZilla,
    zillaBold: webZilla,
  },
  // Native: one font file per weight, so weight is part of the family.
  native: {
    arvo: native(theme.fontFamilies.native.arvoRegular),
    amaranth: native(theme.fontFamilies.native.amaranthRegular),
    zilla: native(theme.fontFamilies.native.zillaSlabRegular),
    arvoBold: native(theme.fontFamilies.native.arvoBold),
    amaranthBold: native(theme.fontFamilies.native.amaranthBold),
    zillaLight: native(theme.fontFamilies.native.zillaSlabLight),
    zillaBold: native(theme.fontFamilies.native.zillaSlabBold),
  },
};

const containers: Array<[string, number]> = [
  ['form', theme.sizes.layout.form],
  ['content', theme.sizes.layout.content],
  ['wide', theme.sizes.layout.wideContent],
  ['measure', theme.sizes.layout.bodyMeasure],
  ['narrow', theme.sizes.layout.bodyNarrow],
];

function decl(indent: string, name: string, value: string) {
  return `${indent}--suit-${name}: ${value};`;
}

function colorBlock(colors: Colors, indent: string, { splitBrand }: { splitBrand: boolean }) {
  const lines = colorVars.map(([name, key]) => decl(indent, `color-${name}`, colors[key]));
  if (splitBrand) lines.push('');
  lines.push(...brandVars.map(([name, key]) => decl(indent, `color-${name}`, colors[key])));
  return lines;
}

function scaleBlock(
  indent: string,
  fontSet: FontSet,
  radiusControl: string,
  { annotateRadiusControl }: { annotateRadiusControl: boolean },
) {
  const lines: string[] = [
    decl(indent, 'font-arvo', fontSet.arvo),
    decl(indent, 'font-amaranth', fontSet.amaranth),
    decl(indent, 'font-zilla', fontSet.zilla),
    decl(indent, 'font-arvo-bold', fontSet.arvoBold),
    decl(indent, 'font-amaranth-bold', fontSet.amaranthBold),
    decl(indent, 'font-zilla-light', fontSet.zillaLight),
    decl(indent, 'font-zilla-bold', fontSet.zillaBold),
    '',
    ...Object.entries(theme.spacing).map(([k, v]) => decl(indent, `spacing-${k}`, px(v))),
    '',
    ...Object.entries(theme.borderRadius).map(([k, v]) => decl(indent, `radius-${k}`, px(v))),
    '',
  ];
  if (annotateRadiusControl) {
    lines.push(
      `${indent}/* Shared form-control corner radius: keep buttons, inputs and selects congruent. */`,
    );
  }
  lines.push(
    decl(indent, 'radius-control', radiusControl),
    '',
    ...Object.entries(theme.fontSizes).map(([k, v]) => decl(indent, `text-${k}`, px(v))),
    '',
    ...Object.entries(theme.letterSpacings).map(([k, v]) => decl(indent, `tracking-${k}`, v)),
    '',
    ...containers.map(([k, v]) => decl(indent, `container-${k}`, px(v))),
  );
  return lines;
}

function variablesCss(): string {
  return [
    HEADER + ':root {',
    '  color-scheme: light;',
    ...colorBlock(suitThemeLight.colors, '  ', { splitBrand: true }),
    '',
    ...scaleBlock('  ', fonts.web, 'var(--suit-radius-md)', { annotateRadiusControl: true }),
    '}',
    '',
    '.dark {',
    '  color-scheme: dark;',
    ...colorBlock(suitThemeDark.colors, '  ', { splitBrand: true }),
    '}',
    '',
  ].join('\n');
}

function nativeThemeCss(): string {
  return [
    HEADER + "@import './theme-core.css';",
    "@import './semantic.css';",
    '',
    '@layer theme {',
    '  :root {',
    ...scaleBlock('    ', fonts.native, px(theme.borderRadius.md), {
      annotateRadiusControl: false,
    }),
    '',
    '    @variant light {',
    ...colorBlock(suitThemeLight.colors, '      ', { splitBrand: false }),
    '    }',
    '',
    '    @variant dark {',
    ...colorBlock(suitThemeDark.colors, '      ', { splitBrand: false }),
    '    }',
    '  }',
    '}',
    '',
  ].join('\n');
}

function suitTokensCss(): string {
  return [
    HEADER + '/* Web base styles + legacy alias.',
    ' *',
    ' * Colors are NOT defined here: they come from variables.css and switch',
    ' * with the single web theme mechanism, the `dark` class on <html>',
    ' * (set before paint by ThemeScript from @17suit/ui-web). This file used',
    ' * to re-declare four colors via prefers-color-scheme, which fought that',
    ' * mechanism.',
    ' */',
    ':root {',
    '  --suit-color-bg: var(--suit-color-background);',
    '}',
    '',
    'html,',
    'body {',
    '  margin: 0;',
    '  padding: 0;',
    '  background: var(--suit-color-bg);',
    '  color: var(--suit-color-text);',
    '}',
    '',
    '* {',
    '  box-sizing: border-box;',
    '}',
    '',
  ].join('\n');
}

const outputs: Record<string, string> = {
  'variables.css': variablesCss(),
  'native-theme.css': nativeThemeCss(),
  'suit-tokens.css': suitTokensCss(),
};

const check = process.argv.includes('--check');
const stale: string[] = [];

for (const [file, content] of Object.entries(outputs)) {
  const path = resolve(OUT_DIR, file);
  let current = '';
  try {
    current = readFileSync(path, 'utf8');
  } catch {
    current = '';
  }
  if (current === content) continue;
  if (check) {
    stale.push(file);
  } else {
    writeFileSync(path, content, 'utf8');
    process.stdout.write(`wrote packages/tailwind-config/${file}\n`);
  }
}

if (check && stale.length > 0) {
  process.stderr.write(
    `Design tokens out of date: ${stale.join(', ')}.\n` +
      'Edit packages/design-system/src/tokens.ts and run `pnpm tokens:generate`.\n',
  );
  process.exit(1);
}
if (check) process.stdout.write('Design tokens up to date.\n');
